<script setup lang="ts">
import { reactive, ref, computed } from 'vue'; import { useAuthStore } from '@/stores/auth'; import { useRoute, useRouter } from 'vue-router'; import { ElMessage } from 'element-plus'
const props = defineProps<{ mode: 'login' | 'register' }>(); const auth = useAuthStore(); const route = useRoute(); const router = useRouter(); const loading = ref(false)
const isLogin = computed(() => props.mode === 'login'); const form = reactive({ username: '', nickname: '', password: '', phone: '' })
async function submit() { loading.value = true; try { if (isLogin.value) { await auth.login(form.username, form.password); ElMessage.success('欢迎回来'); router.push(String(route.query.redirect || (auth.isAdmin ? '/admin' : '/'))) } else { await auth.register(form); ElMessage.success('注册成功，请登录'); router.push('/login') } } finally { loading.value = false } }
</script>
<template><section class="auth-page"><div class="auth-side"><span class="brand-mark large">拾</span><h1>让遗失<br>止于相遇</h1><p>每一次发布，都是找回希望的开始。</p></div><div class="auth-panel"><div class="auth-box"><span class="eyebrow">{{ isLogin ? 'WELCOME BACK' : 'JOIN US' }}</span><h2>{{ isLogin ? '登录拾光校园' : '创建校园账号' }}</h2><p>{{ isLogin ? '继续帮助物品找到回家的路' : '加入互助、温暖的校园社区' }}</p><el-form label-position="top" @submit.prevent="submit"><el-form-item label="账号"><el-input v-model="form.username" size="large" placeholder="请输入学号或自定义账号"/></el-form-item><el-form-item v-if="!isLogin" label="昵称"><el-input v-model="form.nickname" size="large" placeholder="请输入昵称"/></el-form-item><el-form-item v-if="!isLogin" label="手机号"><el-input v-model="form.phone" size="large" placeholder="选填，用于线下联系"/></el-form-item><el-form-item label="密码"><el-input v-model="form.password" size="large" type="password" show-password placeholder="至少8位字符" @keyup.enter="submit"/></el-form-item><el-button type="primary" size="large" native-type="submit" :loading="loading" class="full-button">{{ isLogin ? '登录' : '立即注册' }}</el-button></el-form><p class="switch-link">{{ isLogin ? '还没有账号？' : '已有账号？' }}<router-link :to="isLogin ? '/register' : '/login'">{{ isLogin ? '免费注册' : '直接登录' }}</router-link></p></div></div></section></template>
